WITH c_rows AS (
    SELECT cds, `AvgScrMath`, `Charter Funding Type`
    FROM c_cols
    WHERE `AvgScrMath` IS NOT NULL AND `AvgScrMath` > 400
)
SELECT * FROM c_rows;

WITH final_funding_types AS (
    SELECT `Charter Funding Type`
    FROM t_join
    WHERE `Charter Funding Type` IS NOT NULL
)
SELECT * FROM final_funding_types;

WITH final_count AS (
    SELECT COUNT(*) AS answer
    FROM final_funding_types
    WHERE `Charter Funding Type` = 'Directly funded'
)
SELECT * FROM final_count;

WITH final_answer AS (
    SELECT `Charter Funding Type`
    FROM t_join
    WHERE `Charter Funding Type` = 'Directly funded'
)
SELECT * FROM final_answer;

WITH final_result AS (
    SELECT `Charter Funding Type`
    FROM t_join
    WHERE `Charter Funding Type` = 'Directly funded'
)
SELECT * FROM final_result;
